/* Layout: cabecera + barra fija de filtros + rejilla de fichas (pantalla 9:16 que se mueve, voto debajo) */
:root{--bg:#f3f1ee;--panel:#fff;--ink:#17171c;--mute:#6c6a73;--line:#e1ddd8;--accent:#3b4cff;--accent-ink:#fff;--yes:#16a34a;--yes-bg:#dcf5e5;--no:#d62f4b;--no-bg:#fde3e8}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#121216;--panel:#1c1c22;--ink:#f2f0ed;--mute:#9b98a3;--line:#2e2e36;--accent:#7c89ff;--accent-ink:#0d0e1a;--yes:#4ade80;--yes-bg:#12301e;--no:#ff6b84;--no-bg:#3a141d;color-scheme:dark}}
:root[data-theme="dark"]{--bg:#121216;--panel:#1c1c22;--ink:#f2f0ed;--mute:#9b98a3;--line:#2e2e36;--accent:#7c89ff;--accent-ink:#0d0e1a;--yes:#4ade80;--yes-bg:#12301e;--no:#ff6b84;--no-bg:#3a141d;color-scheme:dark}
*{box-sizing:border-box}
body{background:var(--bg);color:var(--ink);font:400 14px/1.45 Inter,system-ui,sans-serif;padding-inline:max(16px,env(safe-area-inset-left,0px)) max(16px,env(safe-area-inset-right,0px));padding-block:28px 40px}
body::before{content:"";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);background:var(--bg);z-index:30}
.wrap{max-width:1180px;margin:0 auto}
h1{font:800 30px/1.1 'Space Grotesk',Inter,sans-serif;margin:0 0 8px;letter-spacing:-.02em;text-wrap:balance}
.lead{max-width:62ch;color:var(--mute);margin:0 0 20px}
.bar{position:sticky;top:env(safe-area-inset-top,0px);z-index:20;background:var(--bg);padding:10px 0;border-bottom:1px solid var(--line);display:flex;flex-wrap:wrap;gap:10px 16px;align-items:center;margin-bottom:22px}
.chips{display:flex;flex-wrap:wrap;gap:6px}
.chip{border:1px solid var(--line);background:var(--panel);color:var(--ink);border-radius:999px;padding:6px 12px;font:600 12px Inter,sans-serif;cursor:pointer}
.chip[aria-pressed="true"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}
.chip:focus-visible,.vb:focus-visible,.copy:focus-visible,.stage:focus-visible,textarea:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.count{margin-left:auto;font-size:12px;color:var(--mute);font-variant-numeric:tabular-nums}
.copy{background:var(--accent);color:var(--accent-ink);border:0;border-radius:10px;padding:9px 16px;font:800 13px Inter,sans-serif;cursor:pointer}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(248px,1fr));gap:18px}
.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:14px;display:flex;flex-direction:column;gap:10px;min-width:0}
.card[data-v="1"]{border-color:var(--yes);box-shadow:0 0 0 2px var(--yes-bg)}
.card[data-v="-1"]{opacity:.62}
.card[data-v="-1"] .stage{filter:grayscale(.6)}
.stage{position:relative;width:216px;height:384px;border-radius:22px;overflow:hidden;margin:0 auto;box-shadow:0 6px 18px rgba(0,0,0,.18);cursor:pointer;max-width:100%}
.meta{display:flex;flex-direction:column;gap:3px}
.nm{font:800 15px/1.2 'Space Grotesk',Inter,sans-serif}
.fr{font:600 10px Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--mute)}
.ds{font-size:12.5px;color:var(--mute)}
.votes{display:flex;gap:8px}
.vb{flex:1;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:10px;padding:9px 6px;font:700 13px Inter,sans-serif;cursor:pointer}
.vb.y[aria-pressed="true"]{background:var(--yes);border-color:var(--yes);color:#fff}
.vb.n[aria-pressed="true"]{background:var(--no);border-color:var(--no);color:#fff}
.note{width:100%;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:8px;padding:7px 9px;font:400 12px Inter,sans-serif}
.out{margin-top:30px;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:16px}
.out h2{margin:0 0 6px;font:800 18px 'Space Grotesk',Inter,sans-serif}
.out p{margin:0 0 10px;color:var(--mute);font-size:13px}
textarea{width:100%;min-height:200px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--ink);padding:10px;font:12px/1.5 ui-monospace,Menlo,monospace}
.empty{padding:40px 0;color:var(--mute);text-align:center}

/* ===== piezas de las animaciones (siempre sobre su propio fondo, no cambian con el tema) ===== */
.abs{position:absolute}.ly{position:absolute;inset:0;overflow:hidden}
.cam{position:absolute;inset:0;transform-origin:50% 40%}
.hv{font-family:'Archivo Black',Impact,sans-serif;line-height:1}
.ser{font-family:'Playfair Display',Georgia,serif;font-style:italic;font-weight:800}
.sc{position:absolute;left:0;right:0;bottom:21%;text-align:center;font:800 17px Inter,sans-serif;color:#fff;text-shadow:0 2px 7px rgba(0,0,0,.65);padding:0 10px}
.cp{font:italic 800 13px 'Playfair Display',Georgia,serif;text-transform:uppercase;text-align:center;color:#1b1b1f;text-shadow:0 2px 3px rgba(0,0,0,.22)}
.c3{background:#fff;border-radius:14px;box-shadow:0 16px 24px -8px rgba(0,0,0,.38),0 3px 6px rgba(0,0,0,.18)}
.ic{width:54px;height:54px;border-radius:16px;display:grid;place-items:center;font-size:26px;box-shadow:0 12px 18px -6px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.75),inset 0 -4px 7px rgba(0,0,0,.14)}
.chip2{position:absolute;left:10px;top:10px;background:rgba(0,0,0,.55);color:#fff;font:700 10px Inter,sans-serif;padding:4px 8px;border-radius:99px;letter-spacing:.05em}
.sub{position:absolute;left:0;right:0;bottom:0;height:60%;--hd:30%;--ht:8%;--bt:42%;--sk:#d9a57f;--sh:#2b2118;--cl:#1e1e24}
.sub.full{height:100%;--ht:22%;--bt:52%}
.sub .hd{position:absolute;left:50%;top:var(--ht);width:var(--hd);aspect-ratio:1/1.1;transform:translateX(-50%);border-radius:48%;background:var(--sk)}
.sub .hd::before{content:"";position:absolute;inset:-7% -5% 50% -5%;border-radius:50% 50% 30% 30%;background:var(--sh)}
.sub .hd::after{content:"";position:absolute;left:28%;top:52%;width:9%;aspect-ratio:1;border-radius:50%;background:#2a1a12;box-shadow:19px 0 0 #2a1a12}
.sub .bd{position:absolute;left:14%;right:14%;top:var(--bt);bottom:-30%;border-radius:46% 46% 0 0/30% 30% 0 0;background:var(--cl)}
.a{animation-duration:var(--d,.6s);animation-delay:var(--s,0s);animation-fill-mode:both;animation-timing-function:var(--e,cubic-bezier(.2,.9,.3,1.25))}
.pop{animation-name:kPop}.up{animation-name:kUp}.dn{animation-name:kDn}.lf{animation-name:kLf}.rt{animation-name:kRt}.fd{animation-name:kFd}
