@keyframes kMv{from{transform:translate(var(--x0),var(--y0))}to{transform:translate(var(--x1),var(--y1))}}
@keyframes kYel{to{color:#ffe14a;opacity:1}}
@keyframes kInk{to{color:#111;text-shadow:none}}
@keyframes kPress{0%{transform:scale(1)}50%{transform:scale(.8)}100%{transform:scale(1)}}
@keyframes kHideAt{from{opacity:1}to{opacity:0}}
@keyframes kKnobS{to{transform:translateX(24px)}}
@keyframes kDon0{from{--p:100}to{--p:0}}
@keyframes kSeg{0%,28%{transform:translateX(0)}44%,68%{transform:translateX(60px)}84%,100%{transform:translateX(120px)}}
@keyframes kLup{to{transform:scale(1.7)}}
@keyframes kGridMove{from{background-position:0 0}to{background-position:48px 48px}}
@keyframes kBlurGrow{from{filter:blur(0) brightness(1)}to{filter:blur(9px) brightness(.55)}}
@keyframes kGreen{to{background:#18a957;border-color:#18a957}}
@keyframes kKey{0%{transform:none}40%,100%{transform:translateY(5px);box-shadow:0 1px 0 #c9c9d1,0 4px 6px rgba(0,0,0,.2)}}
@keyframes kStripeBar{from{background-position:0 0}to{background-position:28px 0}}
@keyframes kBtn{from{background:#2f5bff}to{background:#18a957}}
@keyframes kRot{0%{transform:rotate(0)}30%,62%{transform:rotate(-4deg) scale(1.09)}100%{transform:rotate(0) scale(1)}}
@keyframes kPanV{from{transform:translateY(0)}to{transform:translateY(-250px)}}
@keyframes kPanH{0%,25%{transform:translateX(0)}60%,100%{transform:translateX(-216px)}}
@keyframes kHand{from{transform:rotate(0)}to{transform:rotate(270deg)}}
@keyframes kNeedle{from{transform:rotate(-80deg)}to{transform:rotate(64deg)}}
@keyframes kPlay{from{left:0}to{left:100%}}
@keyframes kPie{to{--p:100}}
@keyframes kDark{to{background:#1c1c22}}
@keyframes kInv{to{background:#4a4a56}}
@keyframes kSwapA{0%,30%{transform:none}60%,100%{transform:translateY(48px)}}
@keyframes kSwapB{0%,30%{transform:none}60%,100%{transform:translateY(-48px)}}
@keyframes kTab{0%,30%{transform:translateX(0)}50%,100%{transform:translateX(66px)}}
@keyframes kPanelUp{from{top:44%;border-radius:26px 26px 0 0}to{top:0;border-radius:0}}
@keyframes kClipV{from{clip-path:inset(0 0 100% 0)}to{clip-path:inset(0)}}
@keyframes kDivT{from{top:0}to{top:100%}}
@keyframes kRetro{to{transform:translateY(34%) scale(.64);border-radius:30px}}
@keyframes kSelBox{from{width:0;height:0}to{width:140px;height:96px}}
@keyframes kBlueFill{to{background:#2f5bff;border-color:#2f5bff}}
@keyframes kHeatIn{from{opacity:0;transform:scale(.4)}to{opacity:1;transform:scale(1)}}
@keyframes kSelW{from{width:0}to{width:100%}}
@keyframes kSide{to{transform:translate(-58px,60px) scale(.66)}}
@keyframes kSlideD{from{transform:translateY(-100%)}to{transform:none}}
@keyframes kStamp{0%{opacity:0;transform:scale(2.2) rotate(-8deg)}70%{opacity:1;transform:scale(.94) rotate(-8deg)}100%{opacity:1;transform:scale(1) rotate(-8deg)}}
@keyframes kStripeD{from{background-position:0 0}to{background-position:56px 0}}
@keyframes kDotMove{from{background-position:0 0}to{background-position:22px 22px}}
@keyframes kHl{to{background:#e6ecff}}
@keyframes kRise2{0%{opacity:0;transform:translateY(0)}20%{opacity:1}100%{opacity:0;transform:translateY(-44px)}}
@keyframes kHandL2{from{left:0}to{left:80%}}
@keyframes kW80{from{width:0}to{width:80%}}
@media (prefers-reduced-motion:reduce){.stage *{animation-duration:.01s!important;animation-delay:0s!important;animation-iteration-count:1!important}}
@media (max-width:520px){.grid{grid-template-columns:1fr}.count{margin-left:0;width:100%}}
